    B=len(g[0]); s=g[0].index(2)
    arm={(r,s+r) for r in range(B) if s+r<B}|{(r,s-r) for r in range(B) if s-r>=0}
    out=[[0]*B for _ in range(B)]
    for r in range(B):
        for c in range(B):
            d=c-r
            if (d-s)%4==0:
                blocked = any((rr,d+rr) in arm for rr in range(r))
                if not blocked: out[r][c]=1
    return out
